use std::collections::HashMap;
use std::collections::LinkedList;

pub struct LruCache<K, V> {
 capacity: usize,
 map: HashMap<K, LinkedList<Node<K, V>>>,
 list: LinkedList<Node<K, V>>,
}

struct Node<K, V> {
 key: K,
 value: V,
}

impl<K: Eq + Hash + Clone, V: Clone> LruCache<K, V> {
 pub fn new(capacity: usize) -> Self {
 Self {
 capacity,
 map: HashMap::new(),
 list: LinkedList::new(),
 }
 }

 pub fn get(&mut self, key: &K) -> Option<&V> {
 if let Some(node) = self.map.get(key) {
 // Move node to front
 let node = self.list.pop_front().unwrap();
 self.list.push_back(node);
 Some(&node.value)
 } else {
 None
 }
 }

 pub fn put(&mut self, key: K, value: V) {
 if self.map.len() >= self.capacity {
 // Evict least recently used
 let lru = self.list.pop_front().unwrap();
 self.map.remove(&lru.key);
 }
 let node = Node { key: key.clone(), value };
 self.map.insert(key, node);
 self.list.push_back(node);
 }
}

#[cfg(test)]
mod tests {
 use super::*;

 #[test]
 fn test_lru_eviction() {
 let mut cache = LruCache::new(2);
 cache.put(1, "a");
 cache.put(2, "b");
 cache.put(3, "c"); // evicts 1
 assert_eq!(cache.get(&1), None);
 assert_eq!(cache.get(&2), Some(&"b"));
 assert_eq!(cache.get(&3), Some(&"c"));
 }
}
```

**Invariants:**
- `map.len() <= capacity`
- `list.len() == map.len()`
- Every key in `map` has a corresponding node in `list`
- The most recently accessed item is at the back of the list
- The least recently accessed item is at the front of the list

**Complexity:** O(1) average for get/put.

**Safety:** No unsafe code; all operations are safe. The `

